/// User-facing compaction trigger tuning (gh-2098): the `compaction:`
/// yaml keys override the gh-1742 `CompactionSettings.forWindow` curves.
///
/// gh-1742 shipped the hard-coded threshold policy — provider-usage
/// anchored estimates plus proportional headroom
/// (`reserve = min(65536, max(window ~/ 16, legacy curve))`). Three gaps
/// remained: the trigger is not user-configurable, the ~94% default
/// fires late on large-window model classes, and the only lever was
/// lying about the window (`agent.contextWindowCap` also moves the
/// over-window guard). This library adds the config seam:
///
/// - `compaction.triggerRatio` (0 < r < 1, e.g. 0.75): the trigger line
///   sits at `r × window` — the reserve becomes `window − floor(r ×
///   window)`, so EVERY window-derived consumer (both trigger channels,
///   the structured engine's gate, the ctx meter, the spill budget)
///   moves together through the one reserve value.
/// - `compaction.reserveTokens` / `compaction.keepRecentTokens`: direct
///   overrides of the forWindow curve outputs. `triggerRatio` and
///   `reserveTokens` are two spellings of the same knob (the trigger
///   line) — configuring both is a strict config error.
/// - Absent keys → the gh-1742 behavior byte-identically
///   ([applyCompactionTuning] returns the base instance untouched).
///
/// The default decision (documented in `docs/compaction.md` with the
/// benchmark note): the legacy gh-1742 curve stays the default — moving
/// every session to the 0.75–0.80 band multiplies compaction frequency
/// and cost; operators of large-window classes opt in per scope.
///
/// Pure Dart — no dart:io; the yaml surface parses in the CLI config
/// layer (`cli_config.dart`), the application is shared host wiring
/// (`host_wiring.dart`).
library;

import 'dart:math' as math;

import '../exceptions.dart';
import 'compaction.dart' show CompactionSettings;

/// The `compaction:` section's tuning keys (gh-2098). Null fields mean
/// "no opinion" — the forWindow curve stands.
final class CompactionTuning {
  /// Creates a tuning bundle; every field defaults to null (no
  /// override).
  const CompactionTuning({
    this.triggerRatio,
    this.reserveTokens,
    this.keepRecentTokens,
  });

  /// Parses a raw `compaction:` yaml node into the tuning keys. Null
  /// node → null (the section is absent). Unknown keys (`engine`,
  /// `judgeBudgetSeconds`, future keys) are ignored here — the engine
  /// selector and the judge budget have their own parsers.
  ///
  /// Strict: a mistyped value or an out-of-range ratio is a
  /// [ConfigException] naming the key — a typo must surface at boot,
  /// never silently run the default policy (the `compaction:` section
  /// has been strict since issue #148).
  static CompactionTuning? fromSection(Object? node, {required String label}) {
    if (node == null) return null;
    if (node is! Map) {
      throw ConfigException('$label: compaction must be a map, got: $node');
    }
    final tuning = CompactionTuning(
      triggerRatio: _parseTriggerRatio(node['triggerRatio'], label: label),
      reserveTokens: _parseTokens(
        node['reserveTokens'],
        name: 'reserveTokens',
        label: label,
      ),
      keepRecentTokens: _parseTokens(
        node['keepRecentTokens'],
        name: 'keepRecentTokens',
        label: label,
      ),
    );
    _validateExclusivity(
      tuning.triggerRatio,
      tuning.reserveTokens,
      label: label,
    );
    return tuning;
  }

  /// The trigger ratio: fire when the (anchored) context reaches this
  /// fraction of the effective window. Strictly between 0 and 1.
  final double? triggerRatio;

  /// The reserve override (the headroom the trigger fires before),
  /// bypassing the forWindow curve.
  final int? reserveTokens;

  /// The kept-recent region override, bypassing the forWindow curve.
  final int? keepRecentTokens;

  /// Whether no key carries an opinion — the forWindow curve stands.
  bool get isEmpty =>
      triggerRatio == null && reserveTokens == null && keepRecentTokens == null;

  /// The inverse of [isEmpty].
  bool get isNotEmpty => !isEmpty;
}

/// Parses `compaction.triggerRatio` (gh-2098): null when absent; a
/// strictly-between-0-and-1 number otherwise; anything else is a strict
/// [ConfigException] — a typo must surface at boot, not silently keep
/// the legacy curve.
double? _parseTriggerRatio(Object? value, {required String label}) {
  if (value == null) return null;
  if (value is! num) {
    throw ConfigException(
      '$label: compaction.triggerRatio must be a number strictly '
      'between 0 and 1, got: $value',
    );
  }
  final ratio = value.toDouble();
  if (ratio <= 0 || ratio >= 1) {
    throw ConfigException(
      '$label: compaction.triggerRatio must be strictly between 0 and 1, '
      'got: $value',
    );
  }
  return ratio;
}

/// Parses a positive-int `compaction.<name>` token budget (gh-2098);
/// null when absent. Mirrors `parseJudgeBudgetSeconds` (issue #541 —
/// the pattern for `compaction.*` keys).
int? _parseTokens(
  Object? value, {
  required String name,
  required String label,
}) {
  if (value == null) return null;
  if (value is! int) {
    throw ConfigException(
      '$label: compaction.$name must be a positive int, got: $value',
    );
  }
  if (value <= 0) {
    throw ConfigException(
      '$label: compaction.$name must be positive, got: $value',
    );
  }
  return value;
}

void _validateExclusivity(
  double? triggerRatio,
  int? reserveTokens, {
  required String label,
}) {
  if (triggerRatio == null || reserveTokens == null) return;
  throw ConfigException(
    '$label: compaction.triggerRatio and compaction.reserveTokens are '
    'mutually exclusive — the ratio already fixes the trigger line; '
    'configure one of them',
  );
}

/// Merges the config scopes' tuning keys, deepest wins per key
/// (global `~/.fah/config.yaml` < project `.fah/config.yaml` — the same
/// per-key stack the `tools:` section uses). Both absent → null; a
/// merged pair that re-creates the ratio+reserve conflict is a strict
/// [ConfigException] (the scopes may disagree).
CompactionTuning? mergeCompactionTuning({
  CompactionTuning? global,
  CompactionTuning? project,
}) {
  if (global == null && project == null) return null;
  final merged = CompactionTuning(
    triggerRatio: project?.triggerRatio ?? global?.triggerRatio,
    reserveTokens: project?.reserveTokens ?? global?.reserveTokens,
    keepRecentTokens: project?.keepRecentTokens ?? global?.keepRecentTokens,
  );
  _validateExclusivity(
    merged.triggerRatio,
    merged.reserveTokens,
    label: 'resolved compaction tuning',
  );
  return merged;
}

/// Applies the `compaction:` tuning keys over [base] (the resolved
/// forWindow curve, or a host's explicit settings pin) for a model whose
/// (conversation) window is [window].
///
/// Null/empty [tuning] returns [base] IDENTICALLY (same instance) —
/// unset config stays byte-for-byte legacy, the same contract
/// `resolveBenchCompactionSettings` ships.
///
/// The ratio converts to the reserve the trigger consumers already read:
/// `reserve = window − floor(ratio × window)`. `floor` keeps the line AT
/// or BELOW `r × window` — the configured ratio never fires later than
/// configured. The degenerate guards mirror
/// [CompactionSettings.forWindow] so the pipeline invariants survive any
/// override: a reserve over half the window (a ratio below ~0.5) clamps
/// to `window ~/ 4`, a keep over the window clamps to `window ~/ 2` — a
/// pass must always free tokens. Pure.
CompactionSettings applyCompactionTuning(
  CompactionSettings base, {
  required int window,
  CompactionTuning? tuning,
}) {
  if (tuning == null || tuning.isEmpty) return base;
  final ratio = tuning.triggerRatio;
  var reserveTokens = ratio != null
      ? window - (window * ratio).floor()
      : (tuning.reserveTokens ?? base.reserveTokens);
  var keepRecentTokens = tuning.keepRecentTokens ?? base.keepRecentTokens;
  if (reserveTokens >= window ~/ 2) {
    reserveTokens = math.max(128, window ~/ 4);
  }
  if (keepRecentTokens >= window) {
    keepRecentTokens = math.max(256, window ~/ 2);
  }
  return CompactionSettings(
    enabled: base.enabled,
    reserveTokens: reserveTokens,
    keepRecentTokens: keepRecentTokens,
  );
}

/// Host-parity contract for compaction wiring (gh-1077): the ONE place
/// where the compaction window, thresholds, summarizer chain, retry knobs
/// and the enable flag are resolved, shared by the CLI ([AgentCli]) and the
/// Flutter app ([AgentService]).
///
/// The divergence this file exists to prevent: the compaction CORE
/// (`AutoCompactor`) is shared, but every config-driven wire used to be
/// resolved per host with subtly different semantics — the app defaulted
/// its window to a constant instead of the provider catalog, never applied
/// the owner cap (`agent.contextWindowCap`), and could silently disagree
/// with the CLI on the rest. Both hosts now compute their wiring through
/// [resolveCompactionHostWiring] (the CLI via
/// [resolveCliCompactionWiring], the app over its own stores), and the
/// parity test (`flutter_app/test/compaction_host_wiring_test.dart`, AC5)
/// asserts both paths resolve semantic equals over the same inputs —
/// drift in either path fails the test.
///
/// What is deliberately NOT here: the compaction algorithm itself (cut
/// points, summary prompt, token estimation — `compaction.dart`, shared
/// and untouched) and per-host smol stream construction (the CLI resolves
/// the full roles chain through [ModelRolesResolver]; the app maps its
/// stores onto the same resolver — see the app's `StoreBackedRolesMap`).
library;

import '../model.dart';
import '../model_roles/model_resolver.dart';
import '../model_roles/roles_config.dart';
import '../providers/models_endpoint.dart' show fallbackContextWindow;
import '../model_roles/provider_catalog.dart' show catalogProvider;
import 'compaction.dart' show CompactionSettings;
import 'tuning.dart';

/// Compaction is ON by default on every host — the single documented
/// source of truth (gh-1077 fix contract 4). The CLI has no toggle; the
/// app shares this constant so the two hosts cannot silently disagree on
/// whether compaction is even on. A host that ever grows a switch flips
/// THIS default's consumer, not its own local `true`.
const bool compactionEnabledByDefault = true;

/// The summarizer retry ladder both hosts share — the [AutoCompactor]
/// defaults (bounded attempts, linear backoff; overflow-classified failures
/// skip the ladder entirely and route to the next summarizer / the local
/// trim with zero backoff, issue #729). Pinned here so the parity list
/// (window, reserve, summarizer chain, retry policy, enabled) is complete.
const int compactionSummarizerMaxAttempts = 3;

/// First backoff step of the shared summarizer retry ladder (doubled per
/// attempt: 1s, 2s — see [AutoCompactor.baseBackoff]).
const Duration compactionSummarizerBaseBackoff = Duration(seconds: 1);

/// The resolved compaction wiring of ONE host: everything the host needs
/// to gate, size and run a compaction, in the exact shape the parity test
/// compares across hosts.
final class CompactionHostWiring {
  const CompactionHostWiring({
    required this.window,
    required this.conversationWindow,
    required this.settings,
    required this.smolModel,
    required this.enabled,
    this.maxAttempts = compactionSummarizerMaxAttempts,
    this.baseBackoff = compactionSummarizerBaseBackoff,
  });

  /// The EFFECTIVE context window of the main model (owner cap applied via
  /// [effectiveContextWindow]) — the basis the loop's over-window guard
  /// and the ctx meter also use.
  final int window;

  /// What is left of [window] after the host's fixed request overhead
  /// (system prompt / tool instructions). The CLI carries none (0); the
  /// app subtracts its measured on-device overhead. This — not [window] —
  /// is what the compaction thresholds are scaled to and gated on.
  final int conversationWindow;

  /// Compaction thresholds ([CompactionSettings.forWindow] of
  /// [conversationWindow], or the host's explicit override).
  final CompactionSettings settings;

  /// The resolved `smol` summarizer model, when one is configured AND
  /// distinct from the main model (a `smol` equal to the main model is
  /// normalized to `null` — the [AutoCompactor] skips the smol→main
  /// fallback for a same-model pair, so the wiring says so up front).
  /// `null` = the main stream summarizes (main-model fallback as last
  /// resort, gh-1077 fix contract 1).
  final Model? smolModel;

  /// Whether compaction runs at all ([compactionEnabledByDefault] on both
  /// hosts today).
  final bool enabled;

  /// Bounded summarizer retry attempts per pass (shared ladder).
  final int maxAttempts;

  /// First backoff step of the shared ladder (doubled per attempt).
  final Duration baseBackoff;

  /// Whether [other] resolves the same compaction SEMANTICS as this
  /// wiring — the AC5 parity assertion. Models compare by provider/model
  /// identity (Model has no structural equality), settings by their
  /// threshold fields.
  bool sameResolutionAs(CompactionHostWiring other) {
    bool smolSame() {
      final a = smolModel;
      final b = other.smolModel;
      if (a == null || b == null) return a == null && b == null;
      return a.provider == b.provider && a.id == b.id;
    }

    return window == other.window &&
        conversationWindow == other.conversationWindow &&
        settings.enabled == other.settings.enabled &&
        settings.reserveTokens == other.settings.reserveTokens &&
        settings.keepRecentTokens == other.settings.keepRecentTokens &&
        enabled == other.enabled &&
        maxAttempts == other.maxAttempts &&
        baseBackoff == other.baseBackoff &&
        smolSame();
  }
}

/// Resolves one host's compaction wiring from its inputs — the shared
/// semantics both hosts compute through:
///
/// - `window` = [effectiveContextWindow] (owner cap clamps down / raises
///   to the served truth, issues #273/#729);
/// - `conversationWindow` = the effective window minus the host's fixed
///   request overhead (CLI: 0; app: the measured system-prompt / tool
///   instruction tokens);
/// - `settings` = the explicit override when the host plumbed one, else
///   [CompactionSettings.forWindow] of the conversation window — then
///   the gh-2098 `compaction:` tuning keys ([tuning]) apply over either
///   (the yaml section is the deepest explicit user scope; absent keys
///   leave the base instance untouched);
/// - `smolModel` = the resolved `smol` role, kept only when distinct from
///   the main model;
/// - retry/enabled = the shared defaults ([compactionEnabledByDefault],
///   the pinned summarizer ladder).
CompactionHostWiring resolveCompactionHostWiring({
  required Model mainModel,
  Model? smolModel,
  int? contextWindowCap,
  CompactionSettings? settingsOverride,
  CompactionTuning? tuning,
  int systemOverheadTokens = 0,
  bool enabled = compactionEnabledByDefault,
}) {
  final window = effectiveContextWindow(
    mainModel.contextWindow,
    contextWindowCap,
  );
  final conversation = window - systemOverheadTokens;
  final conversationWindow = conversation > 0 ? conversation : 0;
  final distinct =
      smolModel != null &&
      (smolModel.provider != mainModel.provider ||
          smolModel.id != mainModel.id);
  return CompactionHostWiring(
    window: window,
    conversationWindow: conversationWindow,
    settings: applyCompactionTuning(
      settingsOverride ?? CompactionSettings.forWindow(conversationWindow),
      window: conversationWindow,
      tuning: tuning,
    ),
    smolModel: distinct ? smolModel : null,
    enabled: enabled,
  );
}

/// The CLI host path (what `AgentCli` resolves): the `smol` summarizer
/// comes from the roles resolver (`roles.smol` chain with the main-model
/// fallback as last resort), the cap from `agent.contextWindowCap`.
///
/// Throws exactly what [ModelRolesResolver.resolveRole] throws (a chain
/// with no usable entry) — the CLI surfaces that as a loud compaction
/// failure, same as before; call it after the `shouldCompact` gate.
CompactionHostWiring resolveCliCompactionWiring({
  required Model mainModel,
  required ModelRolesResolver? rolesResolver,
  required int? contextWindowCap,
  CompactionSettings? settingsOverride,
  CompactionTuning? tuning,
}) {
  return resolveCompactionHostWiring(
    mainModel: mainModel,
    smolModel: rolesResolver?.resolveRole(smolModelRole)?.model,
    contextWindowCap: contextWindowCap,
    settingsOverride: settingsOverride,
    tuning: tuning,
  );
}

/// Resolves the app's context window for a connection (gh-1077 fix
/// contract 2 / AC3): the endpoint-reported or picker-stored value wins,
/// else the provider-catalog window, else the pinned shared fallback
/// ([fallbackContextWindow], 200000 — pi's smallest modern per-model
/// value; E1: this is the documented answer for unknown/custom providers
/// with no catalog entry).
///
/// A stored value equal to the fallback constant means "nothing was
/// known" (both the pickers and the persisted configs use the constant as
/// their default), so it does not suppress the catalog lookup.
int resolveAppContextWindow({String? providerKind, int? storedWindow}) {
  if (storedWindow != null &&
      storedWindow > 0 &&
      storedWindow != fallbackContextWindow) {
    return storedWindow;
  }
  final catalog = providerKind == null
      ? null
      : catalogProvider(providerKind)?.contextWindow;
  return catalog ?? fallbackContextWindow;
}

